                """).param("id", jobId).param("key", "uploads/" + jobId + "/inventory_frame.csv").update();
        jdbc.sql("UPDATE frame_version SET import_job_id = :job WHERE version_id = :version")
            .param("job", jobId).param("version", frame.getVersionId()).update();

