# Frame Inventory BFF

From the repository root, run `docker compose up --build bff`. Open [Apollo Sandbox](http://127.0.0.1:4000) and run:

```graphql
query ListFrames {
  frames(page: 0, size: 25) {
    items {
      frameId
      versionId
      attributes {
        status
        address
      }
    }
    page
    size
    hasNext
  }
}
```

The query uses the backend's zero-based pagination. Omitted arguments use page
`0` and size `25`. Sizes from `1` through `50` are valid. An empty inventory
returns an empty list with `hasNext: false`.

When Spring rejects invalid input, the GraphQL error has code `BAD_USER_INPUT`.
If the backend supplies validation details, `extensions.fieldViolations`
contains `{ field, description }` entries using backend property paths.
Other input errors may not include this extension.

## Frame lifecycle in Apollo Sandbox

Paste these operations into Sandbox. Run **Create** with variables
`{"id":"sandbox-frame-001"}`. Use a fresh ID for each run, since Spring reserves
frame IDs after their first use, including after deletion.

```graphql

test('exports resolver latency by schema field for queries and mutations', async () => {
  const exporter = new PrometheusExporter({ preventServerStart: true })
  const provider = new MeterProvider({ readers: [exporter] })
  const client = mockClient()
  client.listFrames.mockImplementation(
    (_request, _metadata, _options, callback) => {
      callback(null, { items: [], page: 0, size: 25, hasNext: false })
    },
  )
  client.deleteFrame.mockImplementation(
    (_request, _metadata, _options, callback) => {
      callback(null, {})
    },
  )
  const server = createServer(client)
  server.addPlugin(
    createMetricsPlugin(provider.getMeter('frame-inventory-bff')),
  )

  try {
    await server.executeOperation({
      query: `query ClientQuery {
        aliasedFrames: frames { page }
        frame(frameId: "") { frameId }
        __typename
        secondList: frames(page: -1) { page }
      }`,
    })
    await server.executeOperation({
      query: `mutation ClientMutation {
        aliasedDelete: deleteFrame(frameId: "FRAME-001")
      }`,
    })

    const { resourceMetrics } = await exporter.collect()
    const samples = new PrometheusSerializer().serialize(resourceMetrics)
    const counts = samples
      .split('\n')
      .filter((line) =>
        line.startsWith('bff_graphql_root_field_duration_seconds_count{'),
      )
    expect(counts).toHaveLength(3)
    expect(counts).toEqual(
      expect.arrayContaining([
        expect.stringMatching(/operation_type="query".*field="frames".*\} 2$/),
        expect.stringMatching(/operation_type="query".*field="frame".*\} 1$/),
        expect.stringMatching(
          /operation_type="mutation".*field="deleteFrame".*\} 1$/,
        ),
      ]),
    )
    expect(samples).not.toMatch(
      /ClientQuery|ClientMutation|aliasedFrames|aliasedDelete|FRAME-001/,
    )
  } finally {
    await server.stop()
    await provider.shutdown()
  }
})

